import { ok, fail } from './result.js';
import { getCustomer, normalizeId } from './customers.js';
import { balanceDue, invoiceTotals } from './payments.js';
import { isValidDate, daysBetween } from './dates.js';

/**
 * Generate a statement for a customer showing outstanding invoices.
 * @param {string} customerId
 * @param {Array} invoices list of invoices to filter from
 * @param {string} asOf statement date in YYYY-MM-DD format
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function statement(customerId, invoices, asOf) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate asOf date
  if (!isValidDate(asOf)) return fail('DATE_INVALID');

  // Filter invoices for this customer with status issued or partially_paid
  const customerInvoices = invoices.filter(
    (inv) =>
      inv.customerId === normalizedCustomerId &&
      (inv.status === 'issued' || inv.status === 'partially_paid') &&
      daysBetween(inv.issueDate, asOf) >= 0,
  );

  // Map to statement format and sort by issueDate
  const statementInvoices = customerInvoices
    .map((inv) => ({
      number: inv.number,
      issueDate: inv.issueDate,
      dueDate: inv.dueDate,
      total: invoiceTotals(inv).total,
      due: balanceDue(inv),
    }))
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  // Calculate total due
  const totalDue = statementInvoices.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId: normalizedCustomerId,
    invoices: statementInvoices,
    totalDue,
  });
}

