import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns issued invoices for a customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const invoices = [issued1.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, '2025-0001');
  assert.equal(result.value.invoices[0].issueDate, '2025-01-15');
});

test('statement includes partially_paid invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const payment = recordPayment(issued1.value, { amount: 5000, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const invoices = [payment.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, result.value.totalDue);
});

test('statement excludes draft invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);

  const invoices = [inv1.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement excludes paid invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const payment = recordPayment(issued1.value, { amount: 114950, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const invoices = [payment.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement excludes invoices after asOf date', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const invoices = [issued1.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement includes invoices on asOf date', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const invoices = [issued1.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = statement('C-999', [], '2025-02-01');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('statement returns DATE_INVALID for invalid asOf date', () => {
  const result = statement('C-001', [], '2025-2-1');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('statement calculates due and totalDue correctly', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const payment = recordPayment(issued1.value, { amount: 30000, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const invoices = [payment.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  const inv = result.value.invoices[0];
  // Total is 114950 (95 + 19.95 VAT), due is 114950 - 30000 = 84950
  assert.equal(inv.total, 114950);
  assert.equal(inv.due, 84950);
  assert.equal(result.value.totalDue, 84950);
});

test('statement returns empty invoices list if no matching invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);

  const invoices = [inv1.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement sorts invoices by issueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['2025-0001']);
  assert.equal(issued2.ok, true);

  const invoices = [issued1.value, issued2.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2025-01-10');
  assert.equal(result.value.invoices[1].issueDate, '2025-01-20');
});

test('statement normalizes customer ID', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const invoices = [issued1.value];
  const result = statement('c-001 ', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
});

test('statement with multiple invoices calculates totalDue correctly', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['2025-0001']);
  assert.equal(issued2.ok, true);

  const payment1 = recordPayment(issued1.value, { amount: 50000, date: '2025-01-15' });
  assert.equal(payment1.ok, true);

  const invoices = [payment1.value, issued2.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  // inv1: total 114950, due 64950 (114950 - 50000)
  // inv2: total 229900, due 229900
  // totalDue = 64950 + 229900 = 294850
  assert.equal(result.value.totalDue, 294850);
});

test('statement includes invoice number, issueDate, and dueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const invoices = [issued1.value];
  const result = statement('C-001', invoices, '2025-02-01');

  assert.equal(result.ok, true);
  const inv = result.value.invoices[0];
  assert.equal(inv.number, '2025-0001');
  assert.equal(inv.issueDate, '2025-01-15');
  assert.equal(inv.dueDate, '2025-01-29');
});

