  const inv = result.value.invoices[0];
  // Total is 11495 (95 + 1.95 VAT), due is 11495 - 5000 = 6495
  assert.equal(inv.total, 11495);
  assert.equal(inv.due, 6495);
  assert.equal(result.value.totalDue, 6495);
});

test('statement returns empty invoices list if no matching invoices', () => {
